    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_pressure = 0
    weak_pressure = 0
    desperate_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(bid)
                    if bid >= 90:
                        strong_pressure += 1
                    elif bid <= 50:
                        weak_pressure += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 28.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Supply regime: with req 13, supply < 26 means usually only one player can be fully satisfied.
    high_supply = supply >= 23
    mid_supply = supply >= 19

    # Emergency survival mode
    if hp <= 2 or no_water >= 2:
        if high_supply:
            bid = 96.0 if highest_prev < 100 else highest_prev + 2.5
        else:
            bid = 108.0 if highest_prev < 110 else highest_prev + 2.0
        return float(min(budget, bid))

    # Late game: spend more if still healthy enough to capitalize
    if day >= 8:
        if high_supply and strong_pressure <= 1:
            bid = max(78.0, highest_prev + 1.5)
        else:
            bid = max(92.0, highest_prev + 1.0)
        return float(min(budget, bid))

    # Early/mid game conservation against chronic overbidders
    if strong_pressure >= 2 and not high_supply and hp >= 4:
        bid = 18.0
    elif high_supply:
        if weak_pressure >= 1 and avg_prev < 85:
            bid = max(72.0, highest_prev + 1.5)
        else:
            bid = 84.0 if hp >= 5 else 92.0
    elif mid_supply:
        if desperate_opp >= 2:
            bid = 32.0 if hp >= 5 else 88.0
        else:
            bid = 46.0 if hp >= 5 else 86.0
    else:
        bid = 24.0 if hp >= 5 else 82.0

    # Budget discipline
    if budget < 120:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, max(15.0, budget * 0.22) if hp >= 5 else budget)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Base bid depends on current HP and no-water days
    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Supply tightness: when supply is near MIN, competition likely increases
    # Map supply to a 0..1 tightness score (1 = tight)
    if MAX_SUPPLY <= MIN_SUPPLY:
        tightness = 0.5
    else:
        tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
        if tightness < 0.0:
            tightness = 0.0
        if tightness > 1.0:
            tightness = 1.0

    # Target bid logic:
    # - If others were bidding very high yesterday, match partway.
    # - Otherwise bid around a moderate fraction of salary, scaled by tightness.
    if highest_prev_bid >= DAILY_SALARY * 1.15:
        # Very aggressive field: bid higher if we can survive; otherwise conserve.
        if hp <= 2 or no_water_days >= 1:
            target = DAILY_SALARY * (0.85 + 0.15 * tightness)
        else:
            target = DAILY_SALARY * (0.65 + 0.20 * tightness)
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        # Moderate-high competition
        if hp <= 2 or no_water_days >= 1:
            target = DAILY_SALARY * (0.75 + 0.20 * tightness)
        else:
            target = max(DAILY_SALARY * 0.55, avg_prev_bid * 0.75) * (0.85 + 0.15 * tightness)
    else:
        # Low competition: still bid enough to secure water under tight supply
        target = DAILY_SALARY * (0.45 + 0.25 * tightness)

    # Ensure feasibility: cannot exceed budget
    # Also avoid extreme overbidding early if budget is low
    max_reasonable = budget
    # If budget is tiny, bid proportionally
    if budget <= DAILY_SALARY * 0.6:
        target = min(target, budget * 0.9)

    # Clamp target
    if target < 0.0:
        target = 0.0
    if target > max_reasonable:
        target = max_reasonable

    # If we are already in danger, push harder
    if hp <= 1 or no_water_days >= 2:
        target = min(budget, max(target, DAILY_SALARY * 0.95))

    # Final safety: if budget is extremely low, bid what we can.
    if budget <= 1e-9:
        return 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    bid = DAILY_SALARY * 0.5

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    if highest_prev_bid > 0:
        if my_status['hp'] > 5:
            bid = max(bid, highest_prev_bid + 5.0)
        else:
            bid = max(bid, highest_prev_bid + 10.0)
    else:
        if day_context['day'] == 1:
            bid = DAILY_SALARY * 0.6
        else:
            bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 3:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 5:
        bid = max(bid, DAILY_SALARY * 0.8)
    elif my_status['no_water_days'] > 0:
        bid = max(bid, DAILY_SALARY * 0.7)

    if day_context['day'] >= EPISODE_DAYS - 2:
        bid = max(bid, DAILY_SALARY * 0.9)

    bid = min(bid, my_status['budget'])

    bid = max(bid, 1.0)

    if my_status['hp'] > 3:
        bid = min(bid, DAILY_SALARY * 0.98)

    return bid
